    >
      {t("common.duplicate")}
    </Button>
  );
};

import { parseV3ApiError } from "@/modules/api/lib/v3-client";
import type { Webhook } from "@formbricks/database/prisma-browser";

/** Duplicate a webhook; the new copy gets "Copy of <name>" and its own secret. */
export async function duplicateWebhook({ webhookId }: { webhookId: string }): Promise<Webhook> {
  const response = await fetch(
    `/api/v3/webhooks/${encodeURIComponent(webhookId)}/duplicate`,
    { method: "POST", cache: "no-store", signal: AbortSignal.timeout(15_000) }
  );
  if (!response.ok) throw await parseV3ApiError(response);
  const body = await response.json();
  return body.data;
}

/**
 * POST /api/v3/webhooks/[webhookId]/duplicate — duplicate a webhook.
 * Session-only. Restricted to workspace writers.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { duplicateV3Webhook } from "./lib/operations";
import { ZV3WebhookIdParams } from "./lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "created",
  targetType: "webhook",
  schemas: { params: ZV3WebhookIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    duplicateV3Webhook({
      authentication,
      webhookId: parsedInput.params.webhookId,
      auditLog,
      requestId,
      instance,
    }),
});

import { generateWebhookSecret } from "@/lib/crypto";
import { getOrganizationIdFromWebhookId, getWorkspaceIdFromWebhookId } from "@/lib/utils/helper";
import { getWebhook } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { createWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { successResponse } from "@/app/api/v3/lib/response";
import type { Webhook } from "@formbricks/database/prisma-browser";
import type { TWebhookInput } from "@/modules/integrations/webhooks/types/webhooks";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import type { TV3AuditLog } from "@/app/api/v3/lib/types";

export async function duplicateV3Webhook({
  authentication,
  webhookId,
  auditLog,
  requestId,
  instance,
}: {
  authentication: TV3Authentication;
  webhookId: string;
  auditLog: TV3AuditLog;
  requestId: string;
  instance: string;
}): Promise<Response> {
  const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);

  const existingWebhookResult = await getWebhook(webhookId);
  if (!existingWebhookResult.ok) {
    return import("@/app/api/v3/lib/response").then((r) =>
      r.problemNotFound(requestId, "Webhook", webhookId, instance)
    );
  }

  const existing = existingWebhookResult.data;

  // Build the new webhook input from the existing one
  const webhookInput: TWebhookInput = {
    name: existing.name ? `Copy of ${existing.name}` : null,
    url: existing.url,
    triggers: existing.triggers,
    surveyIds: existing.surveyIds,
  };

  const newWebhook = await createWebhook(workspaceId, webhookInput, generateWebhookSecret());

  auditLog.targetId = newWebhook.id;
  auditLog.newObject = webhookInput;

  return successResponse(newWebhook);
}

import { z } from "zod";
import { ZId } from "@formbricks/types/common";

/** Path parameter for webhook-scoped v3 operations. */
export const ZV3WebhookIdParams = z.strictObject({
  webhookId: ZId,
});

export type TV3WebhookIdParams = z.infer<typeof ZV3WebhookIdParams>;
